'use client';

import { User, Bot } from 'lucide-react';
import WeatherCard from './WeatherCard';
import StockCard from './StockCard';

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  components?: Array<{
    type: string;
    data: any;
  }>;
}

interface ChatMessageProps {
  message: Message;
}

export default function ChatMessage({ message }: ChatMessageProps) {
  const isUser = message.role === 'user';

  return (
    <div className={`flex gap-3 p-4 ${isUser ? 'justify-end' : 'justify-start'}`}>
      {!isUser && (
        <div className="flex-shrink-0 w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center">
          <Bot className="w-5 h-5 text-white" />
        </div>
      )}
      
      <div className={`max-w-[80%] ${isUser ? 'order-first' : ''}`}>
        <div
          className={`rounded-lg p-3 ${
            isUser
              ? 'bg-blue-500 text-white ml-auto'
              : 'bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-white'
          }`}
        >
          <div className="whitespace-pre-wrap">{message.content}</div>
        </div>
        
        {/* Render special components */}
        {message.components && message.components.map((component, index) => (
          <div key={index} className="mt-3">
            {component.type === 'weather' && (
              <WeatherCard data={component.data} />
            )}
            {component.type === 'stock' && (
              <StockCard data={component.data} />
            )}
          </div>
        ))}
      </div>

      {isUser && (
        <div className="flex-shrink-0 w-8 h-8 bg-gray-500 rounded-full flex items-center justify-center">
          <User className="w-5 h-5 text-white" />
        </div>
      )}
    </div>
  );
} 