'use client';

import { Cloud, CloudRain, Sun, Wind, Droplets } from 'lucide-react';

interface WeatherData {
  location: string;
  current: {
    temperature: number;
    condition: string;
    humidity: number;
    windSpeed: number;
    icon: string;
  };
  forecast: Array<{
    day: string;
    high: number;
    low: number;
    condition: string;
    icon: string;
  }>;
}

interface WeatherCardProps {
  data: WeatherData;
}

const getWeatherIcon = (iconType: string) => {
  switch (iconType) {
    case 'sunny':
      return <Sun className="w-8 h-8 text-yellow-500" />;
    case 'cloudy':
      return <Cloud className="w-8 h-8 text-gray-500" />;
    case 'partly-cloudy':
      return <Cloud className="w-8 h-8 text-gray-400" />;
    case 'rainy':
      return <CloudRain className="w-8 h-8 text-blue-500" />;
    default:
      return <Sun className="w-8 h-8 text-yellow-500" />;
  }
};

const getSmallWeatherIcon = (iconType: string) => {
  switch (iconType) {
    case 'sunny':
      return <Sun className="w-5 h-5 text-yellow-500" />;
    case 'cloudy':
      return <Cloud className="w-5 h-5 text-gray-500" />;
    case 'partly-cloudy':
      return <Cloud className="w-5 h-5 text-gray-400" />;
    case 'rainy':
      return <CloudRain className="w-5 h-5 text-blue-500" />;
    default:
      return <Sun className="w-5 h-5 text-yellow-500" />;
  }
};

export default function WeatherCard({ data }: WeatherCardProps) {
  return (
    <div className="bg-gradient-to-br from-blue-400 to-blue-600 dark:from-blue-600 dark:to-blue-800 rounded-xl p-6 text-white shadow-lg max-w-md mx-auto my-4">
      {/* Header */}
      <div className="text-center mb-6">
        <h3 className="text-lg font-semibold">{data.location}</h3>
        <p className="text-blue-100 text-sm">Weather Forecast</p>
      </div>

      {/* Current Weather */}
      <div className="text-center mb-6">
        <div className="flex items-center justify-center mb-2">
          {getWeatherIcon(data.current.icon)}
        </div>
        <div className="text-4xl font-bold mb-1">{data.current.temperature}°</div>
        <div className="text-blue-100 mb-4">{data.current.condition}</div>
        
        {/* Current Details */}
        <div className="flex justify-around text-sm">
          <div className="flex items-center space-x-1">
            <Droplets className="w-4 h-4" />
            <span>{data.current.humidity}%</span>
          </div>
          <div className="flex items-center space-x-1">
            <Wind className="w-4 h-4" />
            <span>{data.current.windSpeed} km/h</span>
          </div>
        </div>
      </div>

      {/* 5-Day Forecast */}
      <div className="border-t border-blue-300 pt-4">
        <h4 className="text-sm font-semibold mb-3 text-center">5-Day Forecast</h4>
        <div className="space-y-2">
          {data.forecast.map((day, index) => (
            <div key={index} className="flex items-center justify-between">
              <div className="flex items-center space-x-3 flex-1">
                {getSmallWeatherIcon(day.icon)}
                <span className="text-sm font-medium">{day.day}</span>
              </div>
              <div className="flex items-center space-x-2 text-sm">
                <span className="font-semibold">{day.high}°</span>
                <span className="text-blue-200">{day.low}°</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
} 